async function cyd53commit(req,env){
  cyd53master(env);const b=await cyd53body(req,4000);await cyd53init(env);
  const draft=await env.DB.prepare('SELECT * FROM carteleria_imports53 WHERE id=?').bind(String(b.id||'')).first();if(!draft)cyd53error('No se encontró la carga revisada.',404);
  if(draft.state==='applied')return cyd53json({ok:true,alreadyApplied:true,id:draft.id});
  if(b.revision!==draft.base_revision)cyd53error('La carga requiere una revisión nueva.',409);
  const {candidate,report}=JSON.parse(draft.preview),now=new Date().toISOString(),revision=draft.base_revision+1;
  await env.DB.batch([
    env.DB.prepare('INSERT OR IGNORE INTO carteleria_promo_versions53 (revision,data,saved_at) SELECT revision,data,updated_at FROM carteleria_promos53 WHERE id=1'),
    env.DB.prepare('UPDATE carteleria_promos53 SET data=?,revision=?,updated_at=?,last_import=? WHERE id=1 AND revision=?').bind(JSON.stringify(candidate),revision,now,draft.id,draft.base_revision),
    env.DB.prepare("UPDATE carteleria_imports53 SET state='applied',committed_at=? WHERE id=? AND EXISTS (SELECT 1 FROM carteleria_promos53 WHERE id=1 AND last_import=? AND revision=?)").bind(now,draft.id,draft.id,revision)
  ]);
  const applied=await env.DB.prepare('SELECT state FROM carteleria_imports53 WHERE id=?').bind(draft.id).first();if(applied.state!=='applied')cyd53error('Otra carga modificó las promociones. Revisa el archivo nuevamente.',409);
  return cyd53json({ok:true,id:draft.id,revision,report});
}
async function cyd53fetch(req,env,ctx){
  const url=new URL(req.url),path=url.pathname;
  if(req.method==='OPTIONS')return new Response(null,{status:204,headers:CYD53_HEADERS});
  try{
    if(path==='/health'&&req.method==='GET')return cyd53json({ok:true,version:'v53',servicio:'Cartelería C&D',master:true,promotions:true});
    if(path==='/api/catalogo/version'&&req.method==='GET'){const r=await cyd53state(env);return cyd53json({ok:true,revision:r.revision,day:cyd53day()});}
    if(path==='/api/catalogo'&&req.method==='GET'){const r=await cyd53state(env),catalog=cyd53catalog(r.state);return cyd53json({ok:true,revision:r.revision,updatedAt:r.updated_at,catalog,layout:cyd53layout(catalog)});}
    if(path==='/api/interacciones'&&req.method==='POST')return await cyd53interaction(req,env);
    if(path.startsWith('/api/master/')){
      cyd53master(env);
      if(path==='/api/master/stats'&&req.method==='GET')return await cyd53stats(req,env,url);
      if(path==='/api/master/events'&&req.method==='GET')return await cyd53events(req,env,url);
      if(path==='/api/master/catalog'&&req.method==='GET'){const r=await cyd53state(env);return cyd53json({ok:true,revision:r.revision,updatedAt:r.updated_at,source:r.state.source,baseRows:r.state.base.length,weeklyRows:r.state.weekly.length,catalog:cyd53catalog(r.state)});}
      if(path==='/api/master/imports/preview'&&req.method==='POST')return await cyd53preview(req,env);
      if(path==='/api/master/imports/commit'&&req.method==='POST')return await cyd53commit(req,env);
      if(path==='/api/master/imports'&&req.method==='GET'){await cyd53init(env);const r=await env.DB.prepare("SELECT id,kind,mode,filename,base_revision,state,created_at,committed_at FROM carteleria_imports53 WHERE state='applied' ORDER BY committed_at DESC LIMIT 20").all();return cyd53json({ok:true,imports:r.results});}
      return cyd53json({ok:false,error:'Ruta no encontrada.'},404);
    }
    const asset=G[path==='/'?'/index.html':path];
    if(asset&&!asset.binary&&/javascript|text\/css|text\/html/.test(asset.type)&&['GET','HEAD'].includes(req.method))return new Response(req.method==='HEAD'?null:asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
    return await z.fetch(req,env);
  }catch(e){return cyd53json({ok:false,error:e.status?e.message:e.message&&/archivo|fila|carga|Product Number|Faltan|promociones|Tipo de carga/.test(e.message)?e.message:'No se pudo completar la operación. Reintenta.'},e.status||400);}
}
