async function cyd56route(req,principal,env,url){
 const path=url.pathname;if(!path.startsWith('/api/manual/')&&!path.startsWith('/api/master/manual/'))return null;
 if(req.method!=='GET'){cyd54post(req);cyd54csrf(req,principal);}
 if(path==='/api/manual/products'&&req.method==='GET')return cyd56products(principal,env,url);
 if(path==='/api/manual/contributions'&&req.method==='POST')return cyd56submit(req,principal,env);
 if(path==='/api/master/manual/contributions'&&req.method==='GET')return cyd56contributions(principal,env,url);
 if(path==='/api/master/manual/photo'&&req.method==='GET')return cyd56evidence(principal,env,url);
 if(path==='/api/master/manual/review'&&req.method==='POST')return cyd56review(req,principal,env);
 if(path==='/api/master/manual/publish'&&req.method==='POST'){cyd56master(principal);const body=await cyd53body(req,2000);if(!/^[\w-]{8,80}$/.test(String(body.id||'')))cyd53error('Actualiza antes de publicar.');return cyd54json(await cyd56publish(env,'manual:'+body.id,cyd56actor(principal)));}
 cyd53error('Ruta no encontrada.',404);
}
async function cyd56weeklyCommit(req,env){
 const body=await cyd53body(req.clone(),4000),response=await cyd53commit(req,env);if(!response.ok)return response;
 const result=await response.json(),draft=await env.DB.prepare('SELECT kind,state FROM carteleria_imports53 WHERE id=?').bind(String(body.id||'')).first();
 if(draft?.kind==='weekly'&&draft.state==='applied'){try{result.manualProducts=await cyd56publish(env,'weekly:'+String(body.id),'Actualización semanal');}catch(error){result.manualProducts={ok:false,error:'Las promociones se actualizaron. La maestra requiere una nueva publicación desde Aportes de productos.'};}}
 return cyd54json(result);
}
// V54: acceso por local/mercado, sesiones y gestión de claves sobre la misma D1.
const CYD54_INIT = new WeakMap();
const CYD54_KEYS = new WeakMap();
const CYD54_COOKIE = '__Host-cyd54';
const CYD54_SESSION_MS = 12 * 60 * 60 * 1000;
const CYD54_IDLE_MS = 2 * 60 * 60 * 1000;
const CYD54_WINDOW_MS = 15 * 60 * 1000;

const CYD54_PUBLIC = new Set(['/', '/index.html', '/styles.css', '/access-v54.js', '/access-v54.css', '/category-filters.css', '/products.css', '/manifest.webmanifest', '/favicon.ico']);
const CYD54_JOB_PATHS = new Set(['/trabajo', '/tomar', '/impreso', '/fallo', '/siguiente']);
const cyd54enc = new TextEncoder();
function cyd54b64(bytes) { return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
function cyd54bytes(value) { return Uint8Array.from(atob(String(value).replace(/-/g, '+').replace(/_/g, '/')), c => c.charCodeAt(0)); }
function cyd54random(size = 32) { return cyd54b64(crypto.getRandomValues(new Uint8Array(size))); }
async function cyd54sha(value) { return cyd54b64(new Uint8Array(await crypto.subtle.digest('SHA-256', cyd54enc.encode(value)))); }
function cyd54same(a, b) { a=String(a); b=String(b); let diff=a.length^b.length; for(let i=0;i<Math.max(a.length,b.length);i++)diff|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0); return diff===0; }
function cyd54code(value) { return String(value??'').trim().replace(/^0+(?=\d)/, ''); }
const CYD61_ADMIN = {role:'master',code:'Administrador',key:'master:Administrador'};
const CYD61_FEATURES = {fleje:false,rf:false};

async function cyd61context(env) {
  await cyd54init(env);
  const [rows,settings]=await env.DB.batch([
    env.DB.prepare('SELECT code,name,market_code,market_name FROM carteleria_stores61 ORDER BY code'),
    env.DB.prepare("SELECT value FROM carteleria_config WHERE key='features61'")
  ]);
  const markets=Object.fromEntries(Object.entries(MERCADOS).map(([code,locals])=>[code,[...locals]]));
  const marketNames={...MERCADO_NOMBRES},localMarket={...LOCAL_MERCADO},stores={...CYD54_STORE_NAMES};
  for(const {code,name,market_code:market,market_name:marketName} of rows.results){
    (markets[market]??=[]).push(code);
    marketNames[market]=marketName;
    localMarket[code]=market;
    stores[code]={name,market,marketName};
  }
  const features=settings.results.length?JSON.parse(settings.results[0].value):CYD61_FEATURES;
  return Object.assign(Object.create(env),{roster:{markets,marketNames,localMarket,stores,locals:Object.keys(localMarket)},features});
}
function cyd54account(role, code, roster) {
  code=cyd54code(code);
  if(role==='master')return code===CYD61_ADMIN.code?CYD61_ADMIN:null;
  if(!/^\d{1,4}$/.test(code))return null;
  if(role==='market'&&Object.hasOwn(roster.markets,code))return {role,code,key:'market:'+code,market:code};
  if(role==='store'&&Object.hasOwn(roster.localMarket,code))return {role,code,key:'store:'+code,market:roster.localMarket[code]};
  return null;
}
function cyd54identify(value, roster) {
  if(value.toLowerCase()===CYD61_ADMIN.code.toLowerCase())return CYD61_ADMIN;
  const code=cyd54code(value);
  return cyd54account(Object.hasOwn(roster.markets,code)?'market':'store',code,roster);
}
